def sort_by_num_divisors(nums):
    def ndiv(x):
        return sum(1 for i in range(1, x + 1) if x % i == 0)
    return sorted(nums, key=lambda x: (ndiv(x), x))

def min_left_rotations_to_sort(lst):
    n = len(lst)
    if n <= 1:
        return 0
    target = sorted(lst)
    for k in range(n):
        if lst[k:] + lst[:k] == target:
            return k
    return -1

