def group_by_mod(nums, m):
    d = {}
    for x in nums:
        r = x % m
        d.setdefault(r, []).append(x)
    return {k: sorted(v) for k, v in d.items()}

def convert_between_timezones(time_str, from_offset_min, to_offset_min):
    hh, mm = map(int, time_str.split(":"))
    total = hh * 60 + mm - from_offset_min + to_offset_min
    day_delta = total // 1440
    rem = total % 1440
    return (f"{rem // 60:02d}:{rem % 60:02d}", day_delta)

def split_into_sentences(s):
    sentences = []
    current = []
    for c in s:
        if c in '.!?':
            sentence = "".join(current).strip()
            if sentence:
                sentences.append(sentence)
            current = []
        else:
            current.append(c)
    tail = "".join(current).strip()
    if tail:
        sentences.append(tail)
    return sentences

def previous_prime(n):
    def isp(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    candidate = n - 1
    while candidate >= 2 and not isp(candidate):
        candidate -= 1
    return candidate

def median_index(nums):
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        val = s[n // 2]
    else:
        val = s[n // 2 - 1]
    return nums.index(val)

def longest_increasing_run(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] > lst[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

