def sliding_window_max(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [max(lst[i:i+k]) for i in range(len(lst) - k + 1)]

def sum_of_divisors(n):
    n = abs(n)
    if n == 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            if i * i != n:
                total += n // i
        i += 1
    return total

