    return total

def find_duplicates_only(lst):
    from collections import Counter
    counts = Counter(lst)
    seen = set()
    out = []
    for x in lst:
        if counts[x] > 1 and x not in seen:
            seen.add(x)
            out.append(x)
    return out

def dedent_tabs(text):
    out = []
    for line in text.split("\n"):
        if line.startswith("\t"):
            out.append("    " + line[1:])
        else:
            out.append(line)
    return "\n".join(out)

def rle_longest_run_value(lst):
    if not lst:
        return None
    best_val = lst[0]
    best_len = 1
    cur_val = lst[0]
    cur_len = 1
    for i in range(1, len(lst)):
        if lst[i] == cur_val:
            cur_len += 1
        else:
            cur_val = lst[i]
            cur_len = 1
        if cur_len > best_len:
            best_len = cur_len
            best_val = cur_val
    return best_val

